SELECT d.s_store_id, d.s_store_name, d.return_date_key, d.shift, d.daily_net_loss, LAG(d.daily_net_loss) OVER (PARTITION BY d.s_store_id, d.shift ORDER BY d.return_date_key) AS prev_daily_net_loss, d.daily_net_loss - LAG(d.daily_net_loss) OVER (PARTITION BY d.s_store_id, d.shift ORDER BY d.return_date_key) AS net_loss_change, CASE WHEN d.daily_net_loss - LAG(d.daily_net_loss) OVER (PARTITION BY d.s_store_id, d.shift ORDER BY d.return_date_key) > 0 THEN 'Increasing' WHEN d.daily_net_loss - LAG(d.daily_net_loss) OVER (PARTITION BY d.s_store_id, d.shift ORDER BY d.return_date_key) < 0 THEN 'Decreasing' ELSE 'Stable' END AS trend_category FROM ( SELECT s.s_store_id, s.s_store_name, sr.sr_returned_date_sk AS return_date_key, td.t_shift AS shift, SUM(sr.sr_net_loss) AS daily_net_loss FROM store_returns sr JOIN store s ON sr.sr_store_sk = s.s_store_sk JOIN time_dim td ON sr.sr_return_time_sk = td.t_time_sk GROUP BY s.s_store_id, s.s_store_name, sr.sr_returned_date_sk, td.t_shift ) d ORDER BY d.s_store_id, d.shift, d.return_date_key
